<?php
declare(strict_types=1);
$sql=[
"CREATE TABLE svc_services (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,customer_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,order_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,order_item_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,unit_no INT UNSIGNED NOT NULL,product_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,category_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,name VARCHAR(128) NOT NULL,origin_environment VARCHAR(24) CHARACTER SET ascii NOT NULL,imported BOOLEAN NOT NULL DEFAULT FALSE,status VARCHAR(24) CHARACTER SET ascii NOT NULL CHECK(status IN ('PENDING_PAYMENT','PENDING_APPROVAL','QUEUED','PROVISIONING','ACTIVE','SUSPENDED','CANCEL_SCHEDULED','TERMINATING','TERMINATED','FAILED','UNKNOWN')),version BIGINT UNSIGNED NOT NULL DEFAULT 1,current_operation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,current_period_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,cancel_at DATETIME(6) NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),UNIQUE KEY uq_svc_unit(order_item_id,unit_no),KEY ix_svc_customer(customer_id,status,id),KEY ix_svc_schedule(status,cancel_at,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin",
"CREATE TABLE svc_configs (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,service_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,version BIGINT UNSIGNED NOT NULL,snapshot_encrypted LONGTEXT NOT NULL,fingerprint CHAR(64) CHARACTER SET ascii NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),UNIQUE KEY uq_svc_config(service_id,version),FOREIGN KEY(service_id) REFERENCES svc_services(id)) ENGINE=InnoDB",
"CREATE TABLE svc_prices (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,service_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,customer_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,currency CHAR(3) CHARACTER SET ascii NOT NULL,net_minor BIGINT NOT NULL CHECK(net_minor>=0),tax_minor BIGINT NOT NULL CHECK(tax_minor>=0),total_minor BIGINT NOT NULL CHECK(total_minor=net_minor+tax_minor),snapshot LONGTEXT NOT NULL CHECK(JSON_VALID(snapshot)),created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),KEY ix_svc_price(service_id,created_at,id),FOREIGN KEY(service_id) REFERENCES svc_services(id)) ENGINE=InnoDB",
"CREATE TABLE svc_periods (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,service_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,customer_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,generation INT UNSIGNED NOT NULL,billing_request_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,price_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,cycle_snapshot LONGTEXT NOT NULL CHECK(JSON_VALID(cycle_snapshot)),starts_at DATETIME(6) NULL,ends_at DATETIME(6) NULL,status VARCHAR(24) CHARACTER SET ascii NOT NULL CHECK(status IN ('AWAITING_PAYMENT','PENDING_PROVIDER','VERIFIED','FAILED','UNKNOWN')),version BIGINT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),UNIQUE KEY uq_svc_period(service_id,generation),KEY ix_svc_due(status,ends_at,service_id),FOREIGN KEY(service_id) REFERENCES svc_services(id),FOREIGN KEY(price_id) REFERENCES svc_prices(id)) ENGINE=InnoDB",
"CREATE TABLE svc_ownership_history (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,service_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,from_customer_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,to_customer_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,reason VARCHAR(24) CHARACTER SET ascii NOT NULL,actor_id VARCHAR(64) CHARACTER SET ascii NOT NULL,trace_id CHAR(36) CHARACTER SET ascii NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),KEY ix_svc_ownership(service_id,created_at,id),FOREIGN KEY(service_id) REFERENCES svc_services(id)) ENGINE=InnoDB",
"CREATE TABLE svc_events (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,service_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,customer_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,kind VARCHAR(48) CHARACTER SET ascii NOT NULL,actor_id VARCHAR(64) CHARACTER SET ascii NOT NULL,trace_id CHAR(36) CHARACTER SET ascii NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),KEY ix_svc_event(service_id,created_at,id),FOREIGN KEY(service_id) REFERENCES svc_services(id)) ENGINE=InnoDB",
"CREATE TRIGGER svc_origin_immutable BEFORE UPDATE ON svc_services FOR EACH ROW BEGIN IF NOT(OLD.origin_environment <=> NEW.origin_environment) OR NOT(OLD.imported <=> NEW.imported) OR NOT(OLD.order_item_id <=> NEW.order_item_id) OR NOT(OLD.unit_no <=> NEW.unit_no) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable service origin'; END IF; END",
];
foreach(['svc_configs','svc_prices','svc_ownership_history','svc_events'] as $table){foreach(['UPDATE','DELETE'] as $verb){$sql[]="CREATE TRIGGER {$table}_".strtolower($verb)." BEFORE $verb ON $table FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable service history'";}}
return $sql;
